class Solution { public:long long continuousSubarrays(vector<int>& nums){deque<int> maximum,minimum;int left=0;long long answer=0;for(int right=0;right<(int)nums.size();++right){while(!maximum.empty()&&nums[maximum.back()]<nums[right])maximum.pop_back();while(!minimum.empty()&&nums[minimum.back()]>nums[right])minimum.pop_back();maximum.push_back(right);minimum.push_back(right);while(nums[maximum.front()]-nums[minimum.front()]>2){if(maximum.front()==left)maximum.pop_front();if(minimum.front()==left)minimum.pop_front();++left;}answer+=right-left+1;}return answer;} };
